-- HAC-45. Carrier portal identity, shared catalog commands and carrier-owned receipts.
-- No users, grants, demo data or fabricated OrganizationMember identities.
begin;
create table private.v2_carrier_catalog_receipts (
 carrier_id uuid not null references public.carriers(id), operator_id uuid not null,
 idempotency_key uuid not null, payload_hash text not null check(payload_hash~'^[0-9a-f]{64}$'),
 result jsonb not null, created_at timestamptz not null default now(),
 primary key(carrier_id,operator_id,idempotency_key),
 foreign key(operator_id,carrier_id) references public.carrier_operators(id,carrier_id)
);
alter table private.v2_carrier_catalog_receipts enable row level security;
create index v2_carrier_catalog_receipts_operator_idx on private.v2_carrier_catalog_receipts(operator_id,carrier_id);
revoke all on private.v2_carrier_catalog_receipts from public,anon,authenticated,service_role;

create function private.carrier_portal_catalog_scope(op uuid,k text,c uuid,s uuid,w boolean,i uuid) returns void
language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or c is null or op is distinct from private.identity_carrier(c) then
  raise exception 'FORBIDDEN_CARRIER_IDENTITY' using errcode='PT403';end if;
 if k not in ('carriers','depots','services','partners','areas','lanes','assets','capacity-pools','calendars',
 'maintenances','repositioning-blocks','asset-capabilities','capability-definitions','drivers','vehicle-combinations',
 'driver-assignments','vehicle-assignments') then raise exception 'FORBIDDEN_CATALOG' using errcode='PT403';end if;
 if w and not exists(select 1 from public.carrier_operators where id=op and role='ADMIN') then
  raise exception 'FORBIDDEN_CARRIER_ROLE' using errcode='PT403';end if;
 if (k='carriers' and (i is distinct from c or s is not null))
 or ((k in ('areas','lanes')) is distinct from (s is not null)) then
  raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 if s is not null and not exists(select 1 from public.carrier_services where id=s and carrier_id=c) then
  raise exception 'CATALOG_NOT_FOUND' using errcode='PT404';end if;
end;$$;

alter function private.authorize_v2_catalog(uuid,uuid,text,uuid,uuid,boolean,uuid) rename to authorize_v2_catalog_before_carrier_portal;
create function private.authorize_v2_catalog(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,
 p_service_id uuid,p_write boolean,p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if p_organization_id is not null then
  perform private.authorize_v2_catalog_before_carrier_portal(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,p_write,p_id);
 else perform private.carrier_portal_catalog_scope(p_member_id,p_kind,p_carrier_id,p_service_id,p_write,p_id);end if;
end;$$;

create function private.catalog_receipt(o uuid,m uuid,c uuid,k uuid) returns private.v2_catalog_receipts
language plpgsql set search_path='' as $$declare r private.v2_catalog_receipts;begin
 if o is not null then select * into r from private.v2_catalog_receipts where organization_id=o and member_id=m and idempotency_key=k;
 else select null::uuid,operator_id,idempotency_key,payload_hash,result,created_at into r
  from private.v2_carrier_catalog_receipts where carrier_id=c and operator_id=m and idempotency_key=k;end if;
 return r;end;$$;
create function private.save_catalog_receipt(o uuid,m uuid,c uuid,k uuid,h text,r jsonb) returns void
language plpgsql set search_path='' as $$begin
 if o is not null then insert into private.v2_catalog_receipts(organization_id,member_id,idempotency_key,payload_hash,result) values(o,m,k,h,r);
 else insert into private.v2_carrier_catalog_receipts(carrier_id,operator_id,idempotency_key,payload_hash,result) values(c,m,k,h,r);end if;
end;$$;

-- Existing domain validation is retained; only receipt dispatch and lock scope change.
create or replace function private.command_v2_fleet(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_idempotency_key uuid,p_expected_version integer,p_value jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare t text; s json; h text; receipt private.v2_catalog_receipts%rowtype; current_version integer; saved_id uuid;
 sid uuid; parent_id uuid; cal_id uuid; w jsonb; other_w jsonb; start_at timestamptz; end_at timestamptz; result jsonb; previous jsonb;begin
 if p_service_id is not null or p_carrier_id is null then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'services',p_carrier_id,null,true,null);
 if p_idempotency_key is null or ((p_id is null) is distinct from (p_expected_version is null)) or p_expected_version<1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 t:=private.fleet_target(p_kind);case p_kind
when 'capability-definitions' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"categoryId":{"type":"string","format":"uuid"},"requirements":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"maxWeightKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"temperatureRange":{"anyOf":[{"type":"object","properties":{"minCelsius":{"type":"number"},"maxCelsius":{"type":"number"}},"required":["minCelsius","maxCelsius"],"additionalProperties":false},{"type":"null"}]},"certifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"verifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","categoryId","requirements","maxWeightKg","temperatureRange","certifications","evidence","verifiedAt","validUntil","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'assets' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"mode":{"type":"string","enum":["ROAD","RAIL","SEA","AIR"]},"equipmentType":{"type":"string","enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},"role":{"type":"string","enum":["LOAD_BEARING","AUXILIARY"]},"usefulCapacityKg":{"type":"number","minimum":0},"usableVolumeM3":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"operatingStatus":{"type":"string","enum":["AVAILABLE","IN_SERVICE","MAINTENANCE","OUT_OF_SERVICE"]},"homeDepotId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"provenance":{"type":"string","enum":["OWN","CONTRACTED","PARTNER"]},"partnerId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"roadVehicle":{"anyOf":[{"type":"object","properties":{"plate":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"registrationCode":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"registeredAt":{"anyOf":[{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$"},{"type":"null"}]},"brand":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"model":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"variant":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"bodyType":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"usableDimensions":{"anyOf":[{"type":"object","properties":{"length":{"type":"number","exclusiveMinimum":0},"width":{"type":"number","exclusiveMinimum":0},"height":{"type":"number","exclusiveMinimum":0}},"required":["length","width","height"],"additionalProperties":false},{"type":"null"}]},"grossWeightLimitKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"odometerKm":{"anyOf":[{"type":"number","minimum":0},{"type":"null"}]},"conditionReason":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"axleConfig":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]}},"required":["plate","registrationCode","registeredAt","brand","model","variant","bodyType","usableDimensions","grossWeightLimitKg","odometerKm","conditionReason","axleConfig"],"additionalProperties":false},{"type":"null"}]}},"required":["schemaVersion","serviceId","code","mode","equipmentType","role","usefulCapacityKg","usableVolumeM3","operatingStatus","homeDepotId","provenance","partnerId","evidence","roadVehicle"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'capacity-pools' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"mode":{"type":"string","enum":["ROAD","RAIL","SEA","AIR"]},"equipmentType":{"anyOf":[{"type":"string","enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},{"type":"null"}]},"serviceWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"declaredCapacity":{"type":"object","properties":{"weightKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"volumeM3":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]}},"required":["weightKg","volumeM3"],"additionalProperties":false},"provenance":{"type":"string","enum":["OWN","CONTRACTED","PARTNER"]},"partnerId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"evidence":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"supportedCargoCategoryIds":{"type":"array","items":{"type":"string","format":"uuid"},"maxItems":100},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","code","mode","equipmentType","serviceWindow","declaredCapacity","provenance","partnerId","evidence","supportedCargoCategoryIds","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'calendars' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"capacityPoolId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"timezone":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"horizon":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"lastVerifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"freshness":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"complete":{"type":"boolean"},"availableWindows":{"type":"array","items":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"maxItems":100},"readyPickupAreaId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]}},"required":["schemaVersion","serviceId","assetId","capacityPoolId","timezone","horizon","source","lastVerifiedAt","freshness","validUntil","complete","availableWindows","readyPickupAreaId"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'maintenances' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"type":"string","format":"uuid"},"blockedWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"kind":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"status":{"type":"string","enum":["SCHEDULED","IN_PROGRESS","COMPLETED","CANCELLED"]},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"reason":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"}},"required":["schemaVersion","serviceId","assetId","blockedWindow","kind","status","source","reason"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'repositioning-blocks' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"calendarId":{"type":"string","format":"uuid"},"occupiedWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"origin":{"type":"object","properties":{"label":{"type":"string","minLength":1,"pattern":"\\S"},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"]},"city":{"type":"string","minLength":1,"pattern":"\\S"},"lat":{"anyOf":[{"type":"number","minimum":-90,"maximum":90},{"type":"null"}]},"lng":{"anyOf":[{"type":"number","minimum":-180,"maximum":180},{"type":"null"}]}},"required":["label","countryCode","region","city","lat","lng"],"additionalProperties":false},"nextPickup":{"type":"object","properties":{"label":{"type":"string","minLength":1,"pattern":"\\S"},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"]},"city":{"type":"string","minLength":1,"pattern":"\\S"},"lat":{"anyOf":[{"type":"number","minimum":-90,"maximum":90},{"type":"null"}]},"lng":{"anyOf":[{"type":"number","minimum":-180,"maximum":180},{"type":"null"}]}},"required":["label","countryCode","region","city","lat","lng"],"additionalProperties":false},"estimatedTravelSeconds":{"type":"integer","exclusiveMinimum":0},"status":{"type":"string","enum":["PLANNED","IN_PROGRESS","COMPLETED","CANCELLED"]},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"reason":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"}},"required":["schemaVersion","serviceId","calendarId","occupiedWindow","origin","nextPickup","estimatedTravelSeconds","status","source","reason"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'asset-capabilities' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"type":"string","format":"uuid"},"definitionId":{"type":"string","format":"uuid"},"categoryId":{"type":"string","format":"uuid"},"temperatureRange":{"anyOf":[{"type":"object","properties":{"minCelsius":{"type":"number"},"maxCelsius":{"type":"number"}},"required":["minCelsius","maxCelsius"],"additionalProperties":false},{"type":"null"}]},"certifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"verifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","assetId","definitionId","categoryId","temperatureRange","certifications","evidence","verifiedAt","validUntil","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
end case;
 if not coalesce(extensions.jsonb_matches_schema(s,p_value),false) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 sid:=(p_value->>'serviceId')::uuid;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'areas',p_carrier_id,sid,true,null);
 -- Lock the service before examining references; all fleet commands for one service serialize.
 perform 1 from public.carrier_services where id=sid for update;
 h:=private.hash_v2_freight_payload(jsonb_build_object('kind',p_kind,'carrierId',p_carrier_id,'serviceId',null,'id',p_id,'expectedVersion',p_expected_version,'value',p_value));
 perform pg_advisory_xact_lock(hashtextextended(coalesce(p_organization_id,p_carrier_id)::text||':'||p_member_id::text||':'||p_idempotency_key::text,0));
 receipt:=private.catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key);
 if receipt.idempotency_key is not null then if receipt.payload_hash<>h then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='PT409';end if;
 return jsonb_build_object('record',receipt.result,'replay',true);end if;
 if p_id is not null then
  execute format('select version from public.%I where id=$1 and carrier_id=$2 and carrier_service_id=$3 for update',t) into current_version using p_id,p_carrier_id,sid;
  if current_version is null then raise exception 'CATALOG_NOT_FOUND' using errcode='PT404';end if;
  if current_version<>p_expected_version then raise exception 'STALE_DRAFT' using errcode='PT409';end if;
  previous:=private.fleet_record(p_kind,p_id)->'value';
 end if;
 if p_kind in ('assets','capacity-pools') then
  if (p_value->>'mode') is distinct from (select transport_mode from public.carrier_services where id=sid)
  or ((p_value->>'provenance'='PARTNER') is distinct from (p_value->>'partnerId' is not null)) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_value->>'partnerId' is not null and not exists(select 1 from public.fulfilment_partners where id=(p_value->>'partnerId')::uuid and carrier_id=p_carrier_id) then raise exception 'INVALID_PARTNER_SOURCE' using errcode='PT400';end if;
  if p_kind='assets' then
   if (p_value->>'mode'='ROAD') is distinct from (p_value->>'roadVehicle' is not null)
    or (p_value->>'role'='AUXILIARY' and ((p_value->>'usefulCapacityKg')::numeric<>0 or p_value->>'usableVolumeM3' is not null))
    or (p_value->>'role'='LOAD_BEARING' and (p_value->>'usefulCapacityKg')::numeric<=0) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  else
   if (p_value#>>'{serviceWindow,endsAt}')::timestamptz<=(p_value#>>'{serviceWindow,startsAt}')::timestamptz
    or exists(select 1 from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') id where not exists(select 1 from public.cargo_categories where cargo_categories.id=id::uuid and active))
    or jsonb_array_length(p_value->'supportedCargoCategoryIds')<>(select count(distinct id) from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') id) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end if;
 end if;
 if p_kind='calendars' then
  if num_nonnulls(p_value->>'assetId',p_value->>'capacityPoolId')<>1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if not exists(select 1 from pg_timezone_names where name=p_value->>'timezone') then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  start_at:=(p_value#>>'{horizon,startsAt}')::timestamptz;end_at:=(p_value#>>'{horizon,endsAt}')::timestamptz;
  if end_at<=start_at or (p_value->>'lastVerifiedAt')::timestamptz>now()
   or (p_value->>'validUntil')::timestamptz<=(p_value->>'lastVerifiedAt')::timestamptz
   or (p_value->>'freshness'<>'UNKNOWN' and num_nonnulls(p_value->>'lastVerifiedAt',p_value->>'validUntil')<>2) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  for w in select value from jsonb_array_elements(p_value->'availableWindows') loop
   if (w->>'endsAt')::timestamptz<=(w->>'startsAt')::timestamptz or (w->>'startsAt')::timestamptz<start_at or (w->>'endsAt')::timestamptz>end_at then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p_value->'availableWindows') with ordinality a(w,i),jsonb_array_elements(p_value->'availableWindows') with ordinality b(w,i)
   where a.i<b.i and tstzrange((a.w->>'startsAt')::timestamptz,(a.w->>'endsAt')::timestamptz,'[)') && tstzrange((b.w->>'startsAt')::timestamptz,(b.w->>'endsAt')::timestamptz,'[)')) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_value->>'readyPickupAreaId' is not null and not exists(select 1 from public.service_areas where id=(p_value->>'readyPickupAreaId')::uuid and carrier_service_id=sid and area_role='PICKUP' and coverage='INCLUDE' and active) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_id is not null and (previous->>'assetId',previous->>'capacityPoolId') is distinct from (p_value->>'assetId',p_value->>'capacityPoolId') then raise exception 'IMMUTABLE_CAPACITY_SOURCE' using errcode='PT400';end if;
 end if;
 if p_kind in ('calendars','maintenances','asset-capabilities') and p_value->>'assetId' is not null then
  if not exists(select 1 from public.transport_assets where id=(p_value->>'assetId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
 end if;
 if p_kind='calendars' and p_value->>'capacityPoolId' is not null and not exists(select 1 from public.capacity_pools where id=(p_value->>'capacityPoolId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
 if p_kind in ('asset-capabilities','capability-definitions') then
  if not exists(select 1 from public.cargo_categories where id=(p_value->>'categoryId')::uuid and active)
   or (p_value#>>'{temperatureRange,maxCelsius}')::numeric<(p_value#>>'{temperatureRange,minCelsius}')::numeric
   or ((p_value#>>'{temperatureRange,minCelsius}') is null) is distinct from ((p_value#>>'{temperatureRange,maxCelsius}') is null)
   or (p_value->>'validUntil')::timestamptz<=(p_value->>'verifiedAt')::timestamptz
   or (p_value->>'verifiedAt')::timestamptz>now()
   or jsonb_array_length(p_value->'certifications')<>(select count(distinct v) from jsonb_array_elements_text(p_value->'certifications') v)
   then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_kind='capability-definitions' and jsonb_array_length(p_value->'requirements')<>(select count(distinct v) from jsonb_array_elements_text(p_value->'requirements') v) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_id is not null and (previous->>'assetId',previous->>'categoryId',previous->>'definitionId') is distinct from (p_value->>'assetId',p_value->>'categoryId',p_value->>'definitionId') then raise exception 'IMMUTABLE_CAPABILITY_SOURCE' using errcode='PT400';end if;
  if p_kind='asset-capabilities' and not exists(select 1 from public.cargo_capability_definitions d where d.id=(p_value->>'definitionId')::uuid and d.carrier_id=p_carrier_id and d.carrier_service_id=sid and d.active
   and d.cargo_category_id=(p_value->>'categoryId')::uuid and d.temperature_range is not distinct from nullif(p_value->'temperatureRange','null'::jsonb)
   and d.certifications=p_value->'certifications' and d.evidence is not distinct from p_value->>'evidence'
   and d.verified_at is not distinct from (p_value->>'verifiedAt')::timestamptz and d.valid_until is not distinct from (p_value->>'validUntil')::timestamptz)
   then raise exception 'INVALID_CAPABILITY_DEFINITION' using errcode='PT400';end if;
  if p_kind='capability-definitions' and p_id is not null and exists(select 1 from public.asset_cargo_capabilities a join public.capacity_calendars c on c.transport_asset_id=a.transport_asset_id
   join public.capacity_reservations r on r.capacity_calendar_id=c.id where a.definition_id=p_id and r.status in ('HELD','CONFIRMED') and r.ends_at>now()) then raise exception 'FLEET_COMMITMENT_CONFLICT' using errcode='PT409';end if;
 end if;
 if p_kind in ('maintenances','repositioning-blocks') then
  w:=p_value->case when p_kind='maintenances' then 'blockedWindow' else 'occupiedWindow' end;
  start_at:=(w->>'startsAt')::timestamptz;end_at:=(w->>'endsAt')::timestamptz;
  if end_at<=start_at or (p_kind='repositioning-blocks' and (p_value->>'estimatedTravelSeconds')::integer>extract(epoch from end_at-start_at)) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_kind='repositioning-blocks' then
   if not exists(select 1 from public.capacity_calendars where id=(p_value->>'calendarId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
   if ((p_value#>>'{origin,lat}') is null) is distinct from ((p_value#>>'{origin,lng}') is null)
    or ((p_value#>>'{nextPickup,lat}') is null) is distinct from ((p_value#>>'{nextPickup,lng}') is null) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end if;
  if p_id is not null and p_value->>(case when p_kind='maintenances' then 'assetId' else 'calendarId' end)
   is distinct from previous->>(case when p_kind='maintenances' then 'assetId' else 'calendarId' end) then raise exception 'IMMUTABLE_BLOCK_SOURCE' using errcode='PT400';end if;
 end if;
 -- Serialize against reservations on the same calendar before changing availability.
 if p_kind='calendars' then cal_id:=p_id;
 elsif p_kind='repositioning-blocks' then cal_id:=(p_value->>'calendarId')::uuid;
 elsif p_kind in ('assets','capacity-pools') then
  select id into cal_id from public.capacity_calendars where (p_kind='assets' and transport_asset_id=p_id) or (p_kind='capacity-pools' and capacity_pool_id=p_id);
 elsif p_kind in ('maintenances','asset-capabilities') then select id into cal_id from public.capacity_calendars where transport_asset_id=(p_value->>'assetId')::uuid;
 end if;
 if cal_id is not null then
  perform 1 from public.capacity_calendars where id=cal_id for update;
  if exists(select 1 from public.capacity_reservations where capacity_calendar_id=cal_id and status in ('HELD','CONFIRMED') and ends_at>now()
    and (p_kind not in ('maintenances','repositioning-blocks') or (p_value->>'status' not in ('COMPLETED','CANCELLED') and tstzrange(starts_at,ends_at,'[)')&&tstzrange(start_at,end_at,'[)')))) then
   raise exception 'FLEET_COMMITMENT_CONFLICT' using errcode='PT409';end if;
 end if;
 case p_kind
when 'capability-definitions' then if p_id is null then insert into public.cargo_capability_definitions(carrier_service_id,cargo_category_id,requirements,max_weight_kg,temperature_range,certifications,evidence,verified_at,valid_until,active,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{categoryId}')::uuid,nullif(p_value#>'{requirements}','null'::jsonb),(p_value#>>'{maxWeightKg}')::numeric,nullif(p_value#>'{temperatureRange}','null'::jsonb),nullif(p_value#>'{certifications}','null'::jsonb),(p_value#>>'{evidence}')::text,(p_value#>>'{verifiedAt}')::timestamptz,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{active}')::boolean,true,p_carrier_id) returning id into saved_id;
else update public.cargo_capability_definitions set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,cargo_category_id=(p_value#>>'{categoryId}')::uuid,requirements=nullif(p_value#>'{requirements}','null'::jsonb),max_weight_kg=(p_value#>>'{maxWeightKg}')::numeric,temperature_range=nullif(p_value#>'{temperatureRange}','null'::jsonb),certifications=nullif(p_value#>'{certifications}','null'::jsonb),evidence=(p_value#>>'{evidence}')::text,verified_at=(p_value#>>'{verifiedAt}')::timestamptz,valid_until=(p_value#>>'{validUntil}')::timestamptz,active=(p_value#>>'{active}')::boolean where id=p_id returning id into saved_id;end if;
when 'assets' then if p_id is null then insert into public.transport_assets(carrier_service_id,code,mode,equipment_code,asset_role,max_weight_kg,max_volume_m3,operating_status,active,home_depot_id,fulfilment_source,fulfilment_partner_id,evidence,plate,registration_code,registered_at,brand,model,variant,body_type,usable_dimensions,gross_weight_limit_kg,odometer_km,condition_reason,axle_config,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{code}')::text,(p_value#>>'{mode}')::text,(p_value#>>'{equipmentType}')::text,case when p_value->>'role'='LOAD_BEARING' then 'CARRIER' else 'ESCORT' end,case when p_value->>'role'='AUXILIARY' then null else (p_value#>>'{usefulCapacityKg}')::numeric end,(p_value#>>'{usableVolumeM3}')::numeric,(p_value#>>'{operatingStatus}')::text,(p_value->>'operatingStatus'='AVAILABLE'),(p_value#>>'{homeDepotId}')::uuid,(p_value#>>'{provenance}')::text,(p_value#>>'{partnerId}')::uuid,(p_value#>>'{evidence}')::text,(p_value#>>'{roadVehicle,plate}')::text,(p_value#>>'{roadVehicle,registrationCode}')::text,(p_value#>>'{roadVehicle,registeredAt}')::date,(p_value#>>'{roadVehicle,brand}')::text,(p_value#>>'{roadVehicle,model}')::text,(p_value#>>'{roadVehicle,variant}')::text,(p_value#>>'{roadVehicle,bodyType}')::text,nullif(p_value#>'{roadVehicle,usableDimensions}','null'::jsonb),(p_value#>>'{roadVehicle,grossWeightLimitKg}')::numeric,(p_value#>>'{roadVehicle,odometerKm}')::numeric,(p_value#>>'{roadVehicle,conditionReason}')::text,(p_value#>>'{roadVehicle,axleConfig}')::text,true,p_carrier_id) returning id into saved_id;
else update public.transport_assets set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,code=(p_value#>>'{code}')::text,mode=(p_value#>>'{mode}')::text,equipment_code=(p_value#>>'{equipmentType}')::text,asset_role=case when p_value->>'role'='LOAD_BEARING' then 'CARRIER' else 'ESCORT' end,max_weight_kg=case when p_value->>'role'='AUXILIARY' then null else (p_value#>>'{usefulCapacityKg}')::numeric end,max_volume_m3=(p_value#>>'{usableVolumeM3}')::numeric,operating_status=(p_value#>>'{operatingStatus}')::text,active=(p_value->>'operatingStatus'='AVAILABLE'),home_depot_id=(p_value#>>'{homeDepotId}')::uuid,fulfilment_source=(p_value#>>'{provenance}')::text,fulfilment_partner_id=(p_value#>>'{partnerId}')::uuid,evidence=(p_value#>>'{evidence}')::text,plate=(p_value#>>'{roadVehicle,plate}')::text,registration_code=(p_value#>>'{roadVehicle,registrationCode}')::text,registered_at=(p_value#>>'{roadVehicle,registeredAt}')::date,brand=(p_value#>>'{roadVehicle,brand}')::text,model=(p_value#>>'{roadVehicle,model}')::text,variant=(p_value#>>'{roadVehicle,variant}')::text,body_type=(p_value#>>'{roadVehicle,bodyType}')::text,usable_dimensions=nullif(p_value#>'{roadVehicle,usableDimensions}','null'::jsonb),gross_weight_limit_kg=(p_value#>>'{roadVehicle,grossWeightLimitKg}')::numeric,odometer_km=(p_value#>>'{roadVehicle,odometerKm}')::numeric,condition_reason=(p_value#>>'{roadVehicle,conditionReason}')::text,axle_config=(p_value#>>'{roadVehicle,axleConfig}')::text where id=p_id returning id into saved_id;end if;
when 'capacity-pools' then if p_id is null then insert into public.capacity_pools(carrier_service_id,code,mode,equipment_code,starts_at,ends_at,max_weight_kg,max_volume_m3,fulfilment_source,fulfilment_partner_id,evidence,supported_cargo_category_ids,active,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{code}')::text,(p_value#>>'{mode}')::text,(p_value#>>'{equipmentType}')::text,(p_value#>>'{serviceWindow,startsAt}')::timestamptz,(p_value#>>'{serviceWindow,endsAt}')::timestamptz,(p_value#>>'{declaredCapacity,weightKg}')::numeric,(p_value#>>'{declaredCapacity,volumeM3}')::numeric,(p_value#>>'{provenance}')::text,(p_value#>>'{partnerId}')::uuid,(p_value#>>'{evidence}')::text,array(select v::uuid from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') v),(p_value#>>'{active}')::boolean,true,p_carrier_id) returning id into saved_id;
else update public.capacity_pools set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,code=(p_value#>>'{code}')::text,mode=(p_value#>>'{mode}')::text,equipment_code=(p_value#>>'{equipmentType}')::text,starts_at=(p_value#>>'{serviceWindow,startsAt}')::timestamptz,ends_at=(p_value#>>'{serviceWindow,endsAt}')::timestamptz,max_weight_kg=(p_value#>>'{declaredCapacity,weightKg}')::numeric,max_volume_m3=(p_value#>>'{declaredCapacity,volumeM3}')::numeric,fulfilment_source=(p_value#>>'{provenance}')::text,fulfilment_partner_id=(p_value#>>'{partnerId}')::uuid,evidence=(p_value#>>'{evidence}')::text,supported_cargo_category_ids=array(select v::uuid from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') v),active=(p_value#>>'{active}')::boolean where id=p_id returning id into saved_id;end if;
when 'calendars' then if p_id is null then insert into public.capacity_calendars(carrier_service_id,transport_asset_id,capacity_pool_id,timezone,horizon_starts_at,horizon_ends_at,source_reference,source,observed_at,last_verified_at,provenance_status,freshness,valid_until,complete,available_windows,ready_pickup_area_id,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{assetId}')::uuid,(p_value#>>'{capacityPoolId}')::uuid,(p_value#>>'{timezone}')::text,(p_value#>>'{horizon,startsAt}')::timestamptz,(p_value#>>'{horizon,endsAt}')::timestamptz,(p_value#>>'{source}')::text,(p_value#>>'{source}')::text,(p_value#>>'{lastVerifiedAt}')::timestamptz,(p_value#>>'{lastVerifiedAt}')::timestamptz,(p_value#>>'{freshness}')::text,(p_value#>>'{freshness}')::text,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{complete}')::boolean,nullif(p_value#>'{availableWindows}','null'::jsonb),(p_value#>>'{readyPickupAreaId}')::uuid,true,p_carrier_id) returning id into saved_id;
else update public.capacity_calendars set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,transport_asset_id=(p_value#>>'{assetId}')::uuid,capacity_pool_id=(p_value#>>'{capacityPoolId}')::uuid,timezone=(p_value#>>'{timezone}')::text,horizon_starts_at=(p_value#>>'{horizon,startsAt}')::timestamptz,horizon_ends_at=(p_value#>>'{horizon,endsAt}')::timestamptz,source_reference=(p_value#>>'{source}')::text,source=(p_value#>>'{source}')::text,observed_at=(p_value#>>'{lastVerifiedAt}')::timestamptz,last_verified_at=(p_value#>>'{lastVerifiedAt}')::timestamptz,provenance_status=(p_value#>>'{freshness}')::text,freshness=(p_value#>>'{freshness}')::text,valid_until=(p_value#>>'{validUntil}')::timestamptz,complete=(p_value#>>'{complete}')::boolean,available_windows=nullif(p_value#>'{availableWindows}','null'::jsonb),ready_pickup_area_id=(p_value#>>'{readyPickupAreaId}')::uuid where id=p_id returning id into saved_id;end if;
when 'maintenances' then if p_id is null then insert into public.scheduled_maintenances(carrier_service_id,transport_asset_id,starts_at,ends_at,kind,status,source,reason,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{assetId}')::uuid,(p_value#>>'{blockedWindow,startsAt}')::timestamptz,(p_value#>>'{blockedWindow,endsAt}')::timestamptz,(p_value#>>'{kind}')::text,(p_value#>>'{status}')::text,(p_value#>>'{source}')::text,(p_value#>>'{reason}')::text,true,p_carrier_id) returning id into saved_id;
else update public.scheduled_maintenances set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,transport_asset_id=(p_value#>>'{assetId}')::uuid,starts_at=(p_value#>>'{blockedWindow,startsAt}')::timestamptz,ends_at=(p_value#>>'{blockedWindow,endsAt}')::timestamptz,kind=(p_value#>>'{kind}')::text,status=(p_value#>>'{status}')::text,source=(p_value#>>'{source}')::text,reason=(p_value#>>'{reason}')::text where id=p_id returning id into saved_id;end if;
when 'repositioning-blocks' then if p_id is null then insert into public.repositioning_blocks(carrier_service_id,capacity_calendar_id,starts_at,ends_at,origin,next_pickup,estimated_travel_seconds,status,source,reason,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{calendarId}')::uuid,(p_value#>>'{occupiedWindow,startsAt}')::timestamptz,(p_value#>>'{occupiedWindow,endsAt}')::timestamptz,nullif(p_value#>'{origin}','null'::jsonb),nullif(p_value#>'{nextPickup}','null'::jsonb),(p_value#>>'{estimatedTravelSeconds}')::integer,(p_value#>>'{status}')::text,(p_value#>>'{source}')::text,(p_value#>>'{reason}')::text,true,p_carrier_id) returning id into saved_id;
else update public.repositioning_blocks set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,capacity_calendar_id=(p_value#>>'{calendarId}')::uuid,starts_at=(p_value#>>'{occupiedWindow,startsAt}')::timestamptz,ends_at=(p_value#>>'{occupiedWindow,endsAt}')::timestamptz,origin=nullif(p_value#>'{origin}','null'::jsonb),next_pickup=nullif(p_value#>'{nextPickup}','null'::jsonb),estimated_travel_seconds=(p_value#>>'{estimatedTravelSeconds}')::integer,status=(p_value#>>'{status}')::text,source=(p_value#>>'{source}')::text,reason=(p_value#>>'{reason}')::text where id=p_id returning id into saved_id;end if;
when 'asset-capabilities' then if p_id is null then insert into public.asset_cargo_capabilities(carrier_service_id,transport_asset_id,cargo_category_id,temperature_min_c,temperature_max_c,certifications,evidence,verified_at,valid_until,active,definition_id,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{assetId}')::uuid,(p_value#>>'{categoryId}')::uuid,(p_value#>>'{temperatureRange,minCelsius}')::numeric,(p_value#>>'{temperatureRange,maxCelsius}')::numeric,nullif(p_value#>'{certifications}','null'::jsonb),(p_value#>>'{evidence}')::text,(p_value#>>'{verifiedAt}')::timestamptz,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{active}')::boolean,(p_value#>>'{definitionId}')::uuid,true,p_carrier_id) returning id into saved_id;
else update public.asset_cargo_capabilities set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,transport_asset_id=(p_value#>>'{assetId}')::uuid,cargo_category_id=(p_value#>>'{categoryId}')::uuid,temperature_min_c=(p_value#>>'{temperatureRange,minCelsius}')::numeric,temperature_max_c=(p_value#>>'{temperatureRange,maxCelsius}')::numeric,certifications=nullif(p_value#>'{certifications}','null'::jsonb),evidence=(p_value#>>'{evidence}')::text,verified_at=(p_value#>>'{verifiedAt}')::timestamptz,valid_until=(p_value#>>'{validUntil}')::timestamptz,active=(p_value#>>'{active}')::boolean,definition_id=(p_value#>>'{definitionId}')::uuid where id=p_id returning id into saved_id;end if;
end case;
 if p_kind='capability-definitions' then
  update public.asset_cargo_capabilities set temperature_min_c=(p_value#>>'{temperatureRange,minCelsius}')::numeric,temperature_max_c=(p_value#>>'{temperatureRange,maxCelsius}')::numeric,
   certifications=p_value->'certifications',evidence=p_value->>'evidence',verified_at=(p_value->>'verifiedAt')::timestamptz,valid_until=(p_value->>'validUntil')::timestamptz,active=(p_value->>'active')::boolean
   where definition_id=saved_id;
 end if;
 result:=private.fleet_record(p_kind,saved_id);
 perform private.save_catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key,h,result);
 return jsonb_build_object('record',result,'replay',false);end;$$;

-- Existing domain validation is retained; only receipt dispatch and lock scope change.
create or replace function private.command_v2_crew(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_idempotency_key uuid,p_expected_version integer,p_value jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare t text;s json;sid uuid;h text;receipt private.v2_catalog_receipts%rowtype;current_version integer;saved_id uuid;result jsonb;old_value jsonb;begin
 if p_carrier_id is null or p_service_id is not null then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'services',p_carrier_id,null,true,null);
 if p_idempotency_key is null or ((p_id is null) is distinct from (p_expected_version is null)) or p_expected_version<1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 t:=private.crew_target(p_kind);case p_kind
when 'drivers' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"fullName":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"portalAccountId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"licenseClass":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"licenseValidUntil":{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$"},"licenseTimezone":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"qualifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100,"uniqueItems":true},"experienceYears":{"anyOf":[{"type":"number","minimum":0},{"type":"null"}]},"dutyStatus":{"type":"string","enum":["AVAILABLE","ON_DUTY","OFF_DUTY","SUSPENDED","UNKNOWN"]},"evidence":{"anyOf":[{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},{"type":"null"}]},"availableWindows":{"type":"array","items":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"maxItems":100},"dutyWindow":{"anyOf":[{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},{"type":"null"}]},"maximumDutySeconds":{"anyOf":[{"type":"integer","exclusiveMinimum":0},{"type":"null"}]},"usedDutySeconds":{"type":"integer","minimum":0}},"required":["schemaVersion","serviceId","fullName","portalAccountId","licenseClass","licenseValidUntil","licenseTimezone","qualifications","experienceYears","dutyStatus","evidence","availableWindows","dutyWindow","maximumDutySeconds","usedDutySeconds"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'vehicle-combinations' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"kind":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"configuration":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"assetIds":{"type":"array","items":{"type":"string","format":"uuid"},"minItems":1,"maxItems":20,"uniqueItems":true},"coupledWindow":{"anyOf":[{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},{"type":"null"}]},"evidence":{"type":"array","items":{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},"maxItems":100},"combinedTareKg":{"anyOf":[{"type":"number","minimum":0},{"type":"null"}]},"grossWeightLimitKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"status":{"type":"string","enum":["PROPOSED","COUPLED","RELEASED","CANCELLED"]},"compatibilityEvidence":{"anyOf":[{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},{"type":"null"}]}},"required":["schemaVersion","serviceId","kind","configuration","assetIds","coupledWindow","evidence","combinedTareKg","grossWeightLimitKg","status","compatibilityEvidence"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'driver-assignments' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"executionId":{"type":"string","format":"uuid"},"window":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"status":{"type":"string","enum":["PROPOSED","CONFIRMED","RELEASED","CANCELLED"]},"evidence":{"anyOf":[{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},{"type":"null"}]},"driverId":{"type":"string","format":"uuid"},"role":{"type":"string","enum":["PRIMARY","RELIEF"]},"acceptedLicenseClasses":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100,"uniqueItems":true},"requiredQualifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100,"uniqueItems":true},"policyEvidence":{"anyOf":[{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},{"type":"null"}]}},"required":["schemaVersion","serviceId","executionId","window","status","evidence","driverId","role","acceptedLicenseClasses","requiredQualifications","policyEvidence"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'vehicle-assignments' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"executionId":{"type":"string","format":"uuid"},"window":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"status":{"type":"string","enum":["PROPOSED","CONFIRMED","RELEASED","CANCELLED"]},"evidence":{"anyOf":[{"type":"object","properties":{"reference":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":"string","format":"date-time"},"validUntil":{"type":"string","format":"date-time"},"provenanceStatus":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]}},"required":["reference","verifiedAt","validUntil","provenanceStatus"],"additionalProperties":false},{"type":"null"}]},"assetId":{"type":"string","format":"uuid"},"combinationId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"reservationId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"capacityCommitted":{"type":"object","properties":{"weightKg":{"type":"number","minimum":0},"volumeM3":{"type":"number","minimum":0}},"required":["weightKg","volumeM3"],"additionalProperties":false}},"required":["schemaVersion","serviceId","executionId","window","status","evidence","assetId","combinationId","reservationId","capacityCommitted"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
end case;if not coalesce(extensions.jsonb_matches_schema(s,p_value),false) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 sid:=(p_value->>'serviceId')::uuid;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'areas',p_carrier_id,sid,true,null);
 perform 1 from public.carrier_services where id=sid for update;
 h:=private.hash_v2_freight_payload(jsonb_build_object('kind',p_kind,'carrierId',p_carrier_id,'serviceId',null,'id',p_id,'expectedVersion',p_expected_version,'value',p_value));
 perform pg_advisory_xact_lock(hashtextextended(coalesce(p_organization_id,p_carrier_id)::text||':'||p_member_id::text||':'||p_idempotency_key::text,0));
 receipt:=private.catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key);
 if receipt.idempotency_key is not null then if receipt.payload_hash<>h then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='PT409';end if;return jsonb_build_object('record',receipt.result,'replay',true);end if;
 if p_id is not null then
  execute format('select version from public.%I where id=$1 and carrier_id=$2 and carrier_service_id=$3 for update',t) into current_version using p_id,p_carrier_id,sid;
  if current_version is null then raise exception 'CATALOG_NOT_FOUND' using errcode='PT404';end if;
  if current_version<>p_expected_version then raise exception 'STALE_DRAFT' using errcode='PT409';end if;
  old_value:=private.crew_record(p_kind,p_id)->'value';
  if p_kind in ('driver-assignments','vehicle-assignments') and exists(select 1 from jsonb_each(old_value) e
   where e.key in ('executionId','driverId','assetId','combinationId') and e.value is distinct from p_value->e.key)
  then raise exception 'IMMUTABLE_ASSIGNMENT_SOURCE' using errcode='PT400';end if;
  if p_kind='vehicle-assignments' and old_value->>'reservationId' is not null and old_value->'reservationId' is distinct from p_value->'reservationId'
  then raise exception 'IMMUTABLE_ASSIGNMENT_SOURCE' using errcode='PT400';end if;
 end if;
 if p_kind='vehicle-combinations' and jsonb_array_length(p_value->'assetIds')<>(select count(distinct x) from jsonb_array_elements_text(p_value->'assetIds')x) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 if p_kind='vehicle-combinations' then perform 1 from public.transport_assets where id in(select x::uuid from jsonb_array_elements_text(p_value->'assetIds')x) order by id for update;end if;
 case p_kind
when 'drivers' then if p_id is null then insert into public.drivers(carrier_service_id,full_name,carrier_operator_id,license_class,license_valid_until,license_timezone,qualifications,experience_years,duty_status,evidence,available_windows,duty_starts_at,duty_ends_at,maximum_duty_seconds,used_duty_seconds,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{fullName}')::text,(p_value#>>'{portalAccountId}')::uuid,(p_value#>>'{licenseClass}')::text,(p_value#>>'{licenseValidUntil}')::date,(p_value#>>'{licenseTimezone}')::text,nullif(p_value#>'{qualifications}','null'::jsonb),(p_value#>>'{experienceYears}')::numeric,(p_value#>>'{dutyStatus}')::text,nullif(p_value#>'{evidence}','null'::jsonb),nullif(p_value#>'{availableWindows}','null'::jsonb),(p_value#>>'{dutyWindow,startsAt}')::timestamptz,(p_value#>>'{dutyWindow,endsAt}')::timestamptz,(p_value#>>'{maximumDutySeconds}')::integer,(p_value#>>'{usedDutySeconds}')::integer,p_carrier_id) returning id into saved_id;else update public.drivers set carrier_service_id=(p_value#>>'{serviceId}')::uuid,full_name=(p_value#>>'{fullName}')::text,carrier_operator_id=(p_value#>>'{portalAccountId}')::uuid,license_class=(p_value#>>'{licenseClass}')::text,license_valid_until=(p_value#>>'{licenseValidUntil}')::date,license_timezone=(p_value#>>'{licenseTimezone}')::text,qualifications=nullif(p_value#>'{qualifications}','null'::jsonb),experience_years=(p_value#>>'{experienceYears}')::numeric,duty_status=(p_value#>>'{dutyStatus}')::text,evidence=nullif(p_value#>'{evidence}','null'::jsonb),available_windows=nullif(p_value#>'{availableWindows}','null'::jsonb),duty_starts_at=(p_value#>>'{dutyWindow,startsAt}')::timestamptz,duty_ends_at=(p_value#>>'{dutyWindow,endsAt}')::timestamptz,maximum_duty_seconds=(p_value#>>'{maximumDutySeconds}')::integer,used_duty_seconds=(p_value#>>'{usedDutySeconds}')::integer where id=p_id returning id into saved_id;end if;
when 'vehicle-combinations' then if p_id is null then insert into public.vehicle_combinations(carrier_service_id,kind,configuration,starts_at,ends_at,evidence,combined_tare_kg,gross_weight_limit_kg,status,compatibility_evidence,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{kind}')::text,(p_value#>>'{configuration}')::text,(p_value#>>'{coupledWindow,startsAt}')::timestamptz,(p_value#>>'{coupledWindow,endsAt}')::timestamptz,nullif(p_value#>'{evidence}','null'::jsonb),(p_value#>>'{combinedTareKg}')::numeric,(p_value#>>'{grossWeightLimitKg}')::numeric,(p_value#>>'{status}')::text,nullif(p_value#>'{compatibilityEvidence}','null'::jsonb),p_carrier_id) returning id into saved_id;else update public.vehicle_combinations set carrier_service_id=(p_value#>>'{serviceId}')::uuid,kind=(p_value#>>'{kind}')::text,configuration=(p_value#>>'{configuration}')::text,starts_at=(p_value#>>'{coupledWindow,startsAt}')::timestamptz,ends_at=(p_value#>>'{coupledWindow,endsAt}')::timestamptz,evidence=nullif(p_value#>'{evidence}','null'::jsonb),combined_tare_kg=(p_value#>>'{combinedTareKg}')::numeric,gross_weight_limit_kg=(p_value#>>'{grossWeightLimitKg}')::numeric,status=(p_value#>>'{status}')::text,compatibility_evidence=nullif(p_value#>'{compatibilityEvidence}','null'::jsonb) where id=p_id returning id into saved_id;end if;
when 'driver-assignments' then if p_id is null then insert into public.driver_assignments(carrier_service_id,execution_id,driver_id,starts_at,ends_at,status,evidence,role,accepted_license_classes,required_qualifications,policy_evidence,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{executionId}')::uuid,(p_value#>>'{driverId}')::uuid,(p_value#>>'{window,startsAt}')::timestamptz,(p_value#>>'{window,endsAt}')::timestamptz,(p_value#>>'{status}')::text,nullif(p_value#>'{evidence}','null'::jsonb),(p_value#>>'{role}')::text,nullif(p_value#>'{acceptedLicenseClasses}','null'::jsonb),nullif(p_value#>'{requiredQualifications}','null'::jsonb),nullif(p_value#>'{policyEvidence}','null'::jsonb),p_carrier_id) returning id into saved_id;else update public.driver_assignments set carrier_service_id=(p_value#>>'{serviceId}')::uuid,execution_id=(p_value#>>'{executionId}')::uuid,driver_id=(p_value#>>'{driverId}')::uuid,starts_at=(p_value#>>'{window,startsAt}')::timestamptz,ends_at=(p_value#>>'{window,endsAt}')::timestamptz,status=(p_value#>>'{status}')::text,evidence=nullif(p_value#>'{evidence}','null'::jsonb),role=(p_value#>>'{role}')::text,accepted_license_classes=nullif(p_value#>'{acceptedLicenseClasses}','null'::jsonb),required_qualifications=nullif(p_value#>'{requiredQualifications}','null'::jsonb),policy_evidence=nullif(p_value#>'{policyEvidence}','null'::jsonb) where id=p_id returning id into saved_id;end if;
when 'vehicle-assignments' then if p_id is null then insert into public.vehicle_assignments(carrier_service_id,execution_id,transport_asset_id,starts_at,ends_at,status,evidence,vehicle_combination_id,capacity_reservation_id,capacity_committed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{executionId}')::uuid,(p_value#>>'{assetId}')::uuid,(p_value#>>'{window,startsAt}')::timestamptz,(p_value#>>'{window,endsAt}')::timestamptz,(p_value#>>'{status}')::text,nullif(p_value#>'{evidence}','null'::jsonb),(p_value#>>'{combinationId}')::uuid,(p_value#>>'{reservationId}')::uuid,nullif(p_value#>'{capacityCommitted}','null'::jsonb),p_carrier_id) returning id into saved_id;else update public.vehicle_assignments set carrier_service_id=(p_value#>>'{serviceId}')::uuid,execution_id=(p_value#>>'{executionId}')::uuid,transport_asset_id=(p_value#>>'{assetId}')::uuid,starts_at=(p_value#>>'{window,startsAt}')::timestamptz,ends_at=(p_value#>>'{window,endsAt}')::timestamptz,status=(p_value#>>'{status}')::text,evidence=nullif(p_value#>'{evidence}','null'::jsonb),vehicle_combination_id=(p_value#>>'{combinationId}')::uuid,capacity_reservation_id=(p_value#>>'{reservationId}')::uuid,capacity_committed=nullif(p_value#>'{capacityCommitted}','null'::jsonb) where id=p_id returning id into saved_id;end if;
end case;
 if p_kind='vehicle-combinations' then
  delete from public.vehicle_combination_assets where combination_id=saved_id;
  insert into public.vehicle_combination_assets(combination_id,transport_asset_id,carrier_id,carrier_service_id,starts_at,ends_at,active)
  select saved_id,x::uuid,p_carrier_id,sid,(p_value#>>'{coupledWindow,startsAt}')::timestamptz,(p_value#>>'{coupledWindow,endsAt}')::timestamptz,p_value->>'status'='COUPLED' from jsonb_array_elements_text(p_value->'assetIds')x;
 end if;
 result:=private.crew_record(p_kind,saved_id);
 perform private.save_catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key,h,result);
 return jsonb_build_object('record',result,'replay',false);end;$$;

-- Existing domain validation is retained; only receipt dispatch and lock scope change.
create or replace function private.command_v2_catalog(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,
 p_service_id uuid,p_id uuid,p_idempotency_key uuid,p_expected_version integer,p_value jsonb)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare target record; receipt private.v2_catalog_receipts%rowtype; hash text; current_version integer; saved_id uuid; result jsonb;
 schema json; partner public.fulfilment_partners%rowtype; begin
 if p_kind in ('drivers','vehicle-combinations','driver-assignments','vehicle-assignments') then return private.command_v2_crew(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,p_id,p_idempotency_key,p_expected_version,p_value);end if;
 if p_kind in ('capability-definitions','assets','capacity-pools','calendars','maintenances','repositioning-blocks','asset-capabilities') then return private.command_v2_fleet(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,p_id,p_idempotency_key,p_expected_version,p_value);end if;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,true,p_id);
 if p_idempotency_key is null or ((p_id is null) is distinct from (p_expected_version is null))
 or p_expected_version<1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 case p_kind
when 'preferences' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","objective","maximumWaitMinutes","preferredMode","preferredEquipment","usualBudget","validUntil"],"properties":{"schemaVersion":{"const":"2.0"},"objective":{"anyOf":[{"enum":["LOWEST_COST","FASTEST","WEIGHTED"]},{"type":"null"}]},"maximumWaitMinutes":{"type":["integer","null"],"minimum":0,"maximum":525600},"preferredMode":{"anyOf":[{"enum":["ROAD","RAIL","SEA","AIR"]},{"type":"null"}]},"preferredEquipment":{"anyOf":[{"enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},{"type":"null"}]},"usualBudget":{"type":["object","null"],"additionalProperties":false,"required":["amount","currency"],"properties":{"amount":{"type":"number","exclusiveMinimum":0},"currency":{"const":"USD"}}},"validUntil":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"}}}'::json;
when 'cargo-profiles' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","name","categoryId","typicalUnits","requirements","preferredEquipment","active"],"properties":{"schemaVersion":{"const":"2.0"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"categoryId":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"typicalUnits":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["packageType","quantity","weightPerUnitKg","volumePerUnitM3","dimensionsCm","indivisible","stackable","unitsPerPackage"],"properties":{"packageType":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"quantity":{"type":"integer","minimum":1},"weightPerUnitKg":{"type":"number","exclusiveMinimum":0},"volumePerUnitM3":{"type":"number","exclusiveMinimum":0},"dimensionsCm":{"type":"object","additionalProperties":false,"required":["length","width","height"],"properties":{"length":{"type":"number","exclusiveMinimum":0},"width":{"type":"number","exclusiveMinimum":0},"height":{"type":"number","exclusiveMinimum":0}}},"indivisible":{"type":"boolean"},"stackable":{"type":"boolean"},"unitsPerPackage":{"type":"integer","minimum":1,"maximum":1000000}}},"minItems":0,"maxItems":100},"requirements":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"minItems":0,"maxItems":100,"uniqueItems":true},"preferredEquipment":{"anyOf":[{"enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},{"type":"null"}]},"active":{"type":"boolean"}}}'::json;
when 'cargo-categories' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","code","name","guidance","suggestedEquipment","active"],"properties":{"schemaVersion":{"const":"2.0"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"guidance":{"type":"object","additionalProperties":false,"required":["recommendedEntryMethods","intakeSpecificationSchema","suggestedRequirements","recommendedVehicleClasses"],"properties":{"recommendedEntryMethods":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"minItems":1,"maxItems":100,"uniqueItems":true},"intakeSpecificationSchema":{"type":"object"},"suggestedRequirements":{"type":"object"},"recommendedVehicleClasses":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"minItems":0,"maxItems":100,"uniqueItems":true}}},"suggestedEquipment":{"anyOf":[{"enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},{"type":"null"}]},"active":{"type":"boolean"}}}'::json;
when 'carriers' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","code","commercialName","legalName","businessIdType","businessIdValue","registeredCountry","providerType","status","operationalPhone"],"properties":{"schemaVersion":{"const":"2.0"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"commercialName":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"legalName":{"type":["string","null"],"minLength":1,"maxLength":200,"pattern":"\\S"},"businessIdType":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"businessIdValue":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"registeredCountry":{"type":["string","null"],"pattern":"^[A-Z]{2}$"},"providerType":{"enum":["OWNER_OPERATOR","SMALL_FLEET","CARRIER","ENTERPRISE_CARRIER"]},"status":{"enum":["ACTIVE","INACTIVE"]},"operationalPhone":{"type":["string","null"],"pattern":"^\\+[1-9]\\d{6,14}$"}}}'::json;
when 'depots' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","code","name","location","active","handling"],"properties":{"schemaVersion":{"const":"2.0"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"location":{"type":"object","additionalProperties":false,"required":["label","countryCode","region","city","lat","lng"],"properties":{"label":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"],"minLength":1,"maxLength":120,"pattern":"\\S"},"city":{"type":"string","minLength":1,"maxLength":120,"pattern":"\\S"},"lat":{"type":["number","null"],"minimum":-90,"maximum":90},"lng":{"type":["number","null"],"minimum":-180,"maximum":180}}},"active":{"type":"boolean"},"handling":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"minItems":0,"maxItems":100,"uniqueItems":true}}}'::json;
when 'services' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","mode","serviceClass","maxWeightKg","maxVolumeM3","responseChannels","status","admittedCargoTypes","temperatureRange","requiredCertifications","supportsHazardous","supportsFragile","supportsOversized"],"properties":{"schemaVersion":{"const":"2.0"},"mode":{"enum":["ROAD","RAIL","SEA","AIR"]},"serviceClass":{"enum":["FTL","LTL"]},"maxWeightKg":{"type":["number","null"],"exclusiveMinimum":0},"maxVolumeM3":{"type":["number","null"],"exclusiveMinimum":0},"responseChannels":{"type":"array","items":{"enum":["MANUAL","API","MCP"]},"minItems":1,"maxItems":3,"uniqueItems":true},"status":{"enum":["ACTIVE","INACTIVE"]},"admittedCargoTypes":{"type":"array","items":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"minItems":0,"maxItems":100,"uniqueItems":true},"temperatureRange":{"type":["object","null"],"additionalProperties":false,"required":["minCelsius","maxCelsius"],"properties":{"minCelsius":{"type":"number"},"maxCelsius":{"type":"number"}}},"requiredCertifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"minItems":0,"maxItems":100,"uniqueItems":true},"supportsHazardous":{"type":"boolean"},"supportsFragile":{"type":"boolean"},"supportsOversized":{"type":"boolean"}}}'::json;
when 'areas' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","role","inclusion","geography","source","partnerId","evidence","verifiedAt","validFrom","validUntil","active"],"properties":{"schemaVersion":{"const":"2.0"},"role":{"enum":["PICKUP","DELIVERY"]},"inclusion":{"enum":["INCLUDE","EXCLUDE"]},"geography":{"type":"object","additionalProperties":false,"required":["granularity","countryCode","region","city","postalCode"],"properties":{"granularity":{"enum":["COUNTRY","REGION","CITY","POSTAL_CODE","POLYGON","POINTS"]},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"city":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"postalCode":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"geometry":{"type":["object","null"]}}},"source":{"enum":["OWN","PARTNER"]},"partnerId":{"type":["string","null"],"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"evidence":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"validFrom":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"validUntil":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"active":{"type":"boolean"}}}'::json;
when 'lanes' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","pickupAreaId","deliveryAreaId","kind","mode","borderReviewRequired","evidence","verifiedAt","validFrom","validUntil","active","plannedTransitMinutes","transitProvenanceStatus","crossBorderProhibited","crossBorderProhibitionReference"],"properties":{"schemaVersion":{"const":"2.0"},"pickupAreaId":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"deliveryAreaId":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"kind":{"enum":["DIRECT","WITHIN_AREA"]},"mode":{"enum":["ROAD","RAIL","SEA","AIR"]},"borderReviewRequired":{"type":"boolean"},"evidence":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"},"verifiedAt":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"validFrom":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"validUntil":{"type":["string","null"],"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"active":{"type":"boolean"},"plannedTransitMinutes":{"type":["integer","null"],"minimum":1},"transitProvenanceStatus":{"enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]},"crossBorderProhibited":{"type":"boolean"},"crossBorderProhibitionReference":{"type":["string","null"],"minLength":1,"maxLength":500,"pattern":"\\S"}}}'::json;
when 'partners' then schema:='{"type":"object","additionalProperties":false,"required":["schemaVersion","registeredName","partnerCarrierRef","agreementValidFrom","agreementValidUntil","status","coverageEvidence"],"properties":{"schemaVersion":{"const":"2.0"},"registeredName":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"partnerCarrierRef":{"type":["string","null"],"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"agreementValidFrom":{"type":"string","pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"agreementValidUntil":{"type":"string","pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d+)?(Z|[+-]\\d\\d:\\d\\d)$"},"status":{"enum":["ACTIVE","INACTIVE"]},"coverageEvidence":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"}}}'::json;
end case;
 if not coalesce(extensions.jsonb_matches_schema(schema,p_value),false) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 if p_kind='carriers' and ((p_value->>'businessIdType' is null)<>(p_value->>'businessIdValue' is null))
 or p_kind='depots' and ((p_value#>>'{location,lat}' is null)<>(p_value#>>'{location,lng}' is null))
 or p_kind='services' and (p_value#>>'{temperatureRange,maxCelsius}')::numeric<(p_value#>>'{temperatureRange,minCelsius}')::numeric
 or p_kind in ('areas','lanes') and (p_value->>'validUntil')::timestamptz<=(p_value->>'validFrom')::timestamptz
 or p_kind='partners' and (p_value->>'agreementValidUntil')::timestamptz<=(p_value->>'agreementValidFrom')::timestamptz
 or p_kind='lanes' and ((p_value->>'plannedTransitMinutes' is null) is distinct from (p_value->>'transitProvenanceStatus'='UNKNOWN'))
 then raise exception 'VALIDATION_ERROR' using errcode='PT400'; end if;
 hash:=private.hash_v2_freight_payload(jsonb_build_object('kind',p_kind,'carrierId',p_carrier_id,'serviceId',p_service_id,'id',p_id,'expectedVersion',p_expected_version,'value',p_value));
 perform pg_advisory_xact_lock(hashtextextended(coalesce(p_organization_id,p_carrier_id)::text||':'||p_member_id::text||':'||p_idempotency_key::text,0));
 receipt:=private.catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key);
 if receipt.idempotency_key is not null then
  if receipt.payload_hash<>hash then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='PT409';end if;
  return jsonb_build_object('record',receipt.result,'replay',true);
 end if;
 if p_kind='areas' then
  if ((p_value->>'source'='OWN') is distinct from (p_value->>'partnerId' is null)) then
   raise exception 'INVALID_PARTNER_SOURCE' using errcode='PT400';end if;
  if p_value->>'partnerId' is not null then
   select * into partner from public.fulfilment_partners where id=(p_value->>'partnerId')::uuid and carrier_id=p_carrier_id for share;
   if not found then raise exception 'INVALID_PARTNER_SOURCE' using errcode='PT400';end if;
  end if;
 end if;
 if p_kind='services' and exists(select 1 from jsonb_array_elements_text(p_value->'admittedCargoTypes') v
  where not exists(select 1 from public.cargo_categories where id=v::uuid and active)) then
  raise exception 'INVALID_CARGO_CATEGORY' using errcode='PT400';end if;
 if p_kind='cargo-profiles' and not exists(select 1 from public.cargo_categories where id=(p_value->>'categoryId')::uuid and active) then
  raise exception 'INVALID_CARGO_CATEGORY' using errcode='PT400';end if;
 select * into target from private.catalog_target(p_kind,p_organization_id,p_carrier_id,p_service_id);
 if p_id is not null then
  execute format('select version from public.%I where id=$1 and %s for update',target.table_name,target.scope_sql) into current_version using p_id;
  if current_version is null then raise exception 'CATALOG_NOT_FOUND' using errcode='PT404';end if;
  if current_version<>p_expected_version then raise exception 'STALE_DRAFT' using errcode='PT409';end if;
 end if;
 if p_kind='cargo-categories' and p_id is not null and exists(select 1 from public.cargo_categories where id=p_id and code<>p_value->>'code') then
 raise exception 'IMMUTABLE_CATEGORY_CODE' using errcode='PT400';end if;
 -- Lock the service while revising its mode or creating/revising lanes. This prevents a concurrent mode mismatch.
 if p_kind in ('areas','lanes') then perform 1 from public.carrier_services where id=p_service_id for update;end if;
 if p_kind='services' and p_id is not null and exists(select 1 from public.service_lanes where carrier_service_id=p_id and transport_mode<>p_value->>'mode') then
  raise exception 'SERVICE_MODE_HAS_LANES' using errcode='PT400';end if;
 case p_kind
when 'preferences' then
 if p_id is null then insert into public.organization_preferences (allow_auto_booking,objective,maximum_wait_minutes,preferred_mode,preferred_equipment,usual_budget,valid_until,organization_id) values(false,(p_value#>>'{objective}')::text,(p_value#>>'{maximumWaitMinutes}')::integer,(p_value#>>'{preferredMode}')::text,(p_value#>>'{preferredEquipment}')::text,nullif(p_value#>'{usualBudget}','null'::jsonb),(p_value#>>'{validUntil}')::timestamptz,p_organization_id) returning id into saved_id;
 else update public.organization_preferences set objective=(p_value#>>'{objective}')::text,maximum_wait_minutes=(p_value#>>'{maximumWaitMinutes}')::integer,preferred_mode=(p_value#>>'{preferredMode}')::text,preferred_equipment=(p_value#>>'{preferredEquipment}')::text,usual_budget=nullif(p_value#>'{usualBudget}','null'::jsonb),valid_until=(p_value#>>'{validUntil}')::timestamptz where id=p_id returning id into saved_id;end if;
when 'cargo-profiles' then
 if p_id is null then insert into public.organization_cargo_profiles (profile_name,cargo_category_id,typical_units,requirements,preferred_equipment,active,organization_id,default_entry_method) values((p_value#>>'{name}')::text,(p_value#>>'{categoryId}')::uuid,nullif(p_value#>'{typicalUnits}','null'::jsonb),nullif(p_value#>'{requirements}','null'::jsonb),(p_value#>>'{preferredEquipment}')::text,(p_value#>>'{active}')::boolean,p_organization_id,'PACKAGES') returning id into saved_id;
 else update public.organization_cargo_profiles set profile_name=(p_value#>>'{name}')::text,cargo_category_id=(p_value#>>'{categoryId}')::uuid,typical_units=nullif(p_value#>'{typicalUnits}','null'::jsonb),requirements=nullif(p_value#>'{requirements}','null'::jsonb),preferred_equipment=(p_value#>>'{preferredEquipment}')::text,active=(p_value#>>'{active}')::boolean where id=p_id returning id into saved_id;end if;
when 'cargo-categories' then
 if p_id is null then insert into public.cargo_categories (code,name,recommended_entry_methods,intake_specification_schema,suggested_requirements,recommended_vehicle_classes,suggested_equipment,active) values((p_value#>>'{code}')::text,(p_value#>>'{name}')::text,nullif(p_value#>'{guidance,recommendedEntryMethods}','null'::jsonb),nullif(p_value#>'{guidance,intakeSpecificationSchema}','null'::jsonb),nullif(p_value#>'{guidance,suggestedRequirements}','null'::jsonb),nullif(p_value#>'{guidance,recommendedVehicleClasses}','null'::jsonb),(p_value#>>'{suggestedEquipment}')::text,(p_value#>>'{active}')::boolean) returning id into saved_id;
 else update public.cargo_categories set code=(p_value#>>'{code}')::text,name=(p_value#>>'{name}')::text,recommended_entry_methods=nullif(p_value#>'{guidance,recommendedEntryMethods}','null'::jsonb),intake_specification_schema=nullif(p_value#>'{guidance,intakeSpecificationSchema}','null'::jsonb),suggested_requirements=nullif(p_value#>'{guidance,suggestedRequirements}','null'::jsonb),recommended_vehicle_classes=nullif(p_value#>'{guidance,recommendedVehicleClasses}','null'::jsonb),suggested_equipment=(p_value#>>'{suggestedEquipment}')::text,active=(p_value#>>'{active}')::boolean where id=p_id returning id into saved_id;end if;
when 'carriers' then
 if p_id is null then insert into public.carriers (code,name,legal_name,business_identifier_type,business_identifier_value,registered_country,provider_type,status,operational_phone) values((p_value#>>'{code}')::text,(p_value#>>'{commercialName}')::text,(p_value#>>'{legalName}')::text,(p_value#>>'{businessIdType}')::text,(p_value#>>'{businessIdValue}')::text,(p_value#>>'{registeredCountry}')::text,(p_value#>>'{providerType}')::text,(p_value#>>'{status}')::text,(p_value#>>'{operationalPhone}')::text) returning id into saved_id;
 else update public.carriers set code=(p_value#>>'{code}')::text,name=(p_value#>>'{commercialName}')::text,legal_name=(p_value#>>'{legalName}')::text,business_identifier_type=(p_value#>>'{businessIdType}')::text,business_identifier_value=(p_value#>>'{businessIdValue}')::text,registered_country=(p_value#>>'{registeredCountry}')::text,provider_type=(p_value#>>'{providerType}')::text,status=(p_value#>>'{status}')::text,operational_phone=(p_value#>>'{operationalPhone}')::text where id=p_id returning id into saved_id;end if;
when 'depots' then
 if p_id is null then insert into public.carrier_depots (code,name,country_code,region_code,city,address_line,latitude,longitude,active,handling,carrier_id) values((p_value#>>'{code}')::text,(p_value#>>'{name}')::text,(p_value#>>'{location,countryCode}')::text,(p_value#>>'{location,region}')::text,(p_value#>>'{location,city}')::text,(p_value#>>'{location,label}')::text,(p_value#>>'{location,lat}')::numeric,(p_value#>>'{location,lng}')::numeric,(p_value#>>'{active}')::boolean,nullif(p_value#>'{handling}','null'::jsonb),p_carrier_id) returning id into saved_id;
 else update public.carrier_depots set code=(p_value#>>'{code}')::text,name=(p_value#>>'{name}')::text,country_code=(p_value#>>'{location,countryCode}')::text,region_code=(p_value#>>'{location,region}')::text,city=(p_value#>>'{location,city}')::text,address_line=(p_value#>>'{location,label}')::text,latitude=(p_value#>>'{location,lat}')::numeric,longitude=(p_value#>>'{location,lng}')::numeric,active=(p_value#>>'{active}')::boolean,handling=nullif(p_value#>'{handling}','null'::jsonb) where id=p_id returning id into saved_id;end if;
when 'services' then
 if p_id is null then insert into public.carrier_services (transport_mode,service_type,max_capacity_kg,max_volume_m3,response_channels,active,temperature_min_c,temperature_max_c,required_certifications,supports_hazardous,supports_fragile,supports_oversized,carrier_id,supports_refrigerated) values((p_value#>>'{mode}')::text,(p_value#>>'{serviceClass}')::text,(p_value#>>'{maxWeightKg}')::numeric,(p_value#>>'{maxVolumeM3}')::numeric,nullif(p_value#>'{responseChannels}','null'::jsonb),(p_value->>'status'='ACTIVE'),(p_value#>>'{temperatureRange,minCelsius}')::numeric,(p_value#>>'{temperatureRange,maxCelsius}')::numeric,nullif(p_value#>'{requiredCertifications}','null'::jsonb),(p_value#>>'{supportsHazardous}')::boolean,(p_value#>>'{supportsFragile}')::boolean,(p_value#>>'{supportsOversized}')::boolean,p_carrier_id,(p_value->>'temperatureRange' is not null)) returning id into saved_id;
 else update public.carrier_services set transport_mode=(p_value#>>'{mode}')::text,service_type=(p_value#>>'{serviceClass}')::text,max_capacity_kg=(p_value#>>'{maxWeightKg}')::numeric,max_volume_m3=(p_value#>>'{maxVolumeM3}')::numeric,response_channels=nullif(p_value#>'{responseChannels}','null'::jsonb),active=(p_value->>'status'='ACTIVE'),temperature_min_c=(p_value#>>'{temperatureRange,minCelsius}')::numeric,temperature_max_c=(p_value#>>'{temperatureRange,maxCelsius}')::numeric,required_certifications=nullif(p_value#>'{requiredCertifications}','null'::jsonb),supports_hazardous=(p_value#>>'{supportsHazardous}')::boolean,supports_fragile=(p_value#>>'{supportsFragile}')::boolean,supports_oversized=(p_value#>>'{supportsOversized}')::boolean,supports_refrigerated=(p_value->>'temperatureRange' is not null) where id=p_id returning id into saved_id;end if;
delete from public.carrier_service_cargo_categories where carrier_service_id=saved_id;
insert into public.carrier_service_cargo_categories(carrier_service_id,cargo_category_id) select saved_id,value::uuid from jsonb_array_elements_text(p_value->'admittedCargoTypes');
when 'areas' then
 if p_id is null then insert into public.service_areas (area_role,coverage,granularity,country_code,region_code,city,postal_code,geometry,fulfilment_source,fulfilment_partner_id,evidence_reference,verified_at,valid_from,valid_until,active,carrier_service_id,partner_reference) values((p_value#>>'{role}')::text,(p_value#>>'{inclusion}')::text,(p_value#>>'{geography,granularity}')::text,(p_value#>>'{geography,countryCode}')::text,(p_value#>>'{geography,region}')::text,(p_value#>>'{geography,city}')::text,(p_value#>>'{geography,postalCode}')::text,nullif(p_value#>'{geography,geometry}','null'::jsonb),(p_value#>>'{source}')::text,(p_value#>>'{partnerId}')::uuid,(p_value#>>'{evidence}')::text,(p_value#>>'{verifiedAt}')::timestamptz,(p_value#>>'{validFrom}')::timestamptz,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{active}')::boolean,p_service_id,p_value->>'partnerId') returning id into saved_id;
 else update public.service_areas set area_role=(p_value#>>'{role}')::text,coverage=(p_value#>>'{inclusion}')::text,granularity=(p_value#>>'{geography,granularity}')::text,country_code=(p_value#>>'{geography,countryCode}')::text,region_code=(p_value#>>'{geography,region}')::text,city=(p_value#>>'{geography,city}')::text,postal_code=(p_value#>>'{geography,postalCode}')::text,geometry=nullif(p_value#>'{geography,geometry}','null'::jsonb),fulfilment_source=(p_value#>>'{source}')::text,fulfilment_partner_id=(p_value#>>'{partnerId}')::uuid,evidence_reference=(p_value#>>'{evidence}')::text,verified_at=(p_value#>>'{verifiedAt}')::timestamptz,valid_from=(p_value#>>'{validFrom}')::timestamptz,valid_until=(p_value#>>'{validUntil}')::timestamptz,active=(p_value#>>'{active}')::boolean,partner_reference=p_value->>'partnerId' where id=p_id returning id into saved_id;end if;
when 'lanes' then
 if p_id is null then insert into public.service_lanes (pickup_area_id,delivery_area_id,lane_kind,transport_mode,cross_border_review_required,evidence_reference,verified_at,valid_from,valid_until,active,planned_transit_minutes,transit_provenance_status,cross_border_prohibited,cross_border_prohibition_reference,carrier_service_id) values((p_value#>>'{pickupAreaId}')::uuid,(p_value#>>'{deliveryAreaId}')::uuid,(p_value#>>'{kind}')::text,(p_value#>>'{mode}')::text,(p_value#>>'{borderReviewRequired}')::boolean,(p_value#>>'{evidence}')::text,(p_value#>>'{verifiedAt}')::timestamptz,(p_value#>>'{validFrom}')::timestamptz,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{active}')::boolean,(p_value#>>'{plannedTransitMinutes}')::integer,(p_value#>>'{transitProvenanceStatus}')::text,(p_value#>>'{crossBorderProhibited}')::boolean,(p_value#>>'{crossBorderProhibitionReference}')::text,p_service_id) returning id into saved_id;
 else update public.service_lanes set pickup_area_id=(p_value#>>'{pickupAreaId}')::uuid,delivery_area_id=(p_value#>>'{deliveryAreaId}')::uuid,lane_kind=(p_value#>>'{kind}')::text,transport_mode=(p_value#>>'{mode}')::text,cross_border_review_required=(p_value#>>'{borderReviewRequired}')::boolean,evidence_reference=(p_value#>>'{evidence}')::text,verified_at=(p_value#>>'{verifiedAt}')::timestamptz,valid_from=(p_value#>>'{validFrom}')::timestamptz,valid_until=(p_value#>>'{validUntil}')::timestamptz,active=(p_value#>>'{active}')::boolean,planned_transit_minutes=(p_value#>>'{plannedTransitMinutes}')::integer,transit_provenance_status=(p_value#>>'{transitProvenanceStatus}')::text,cross_border_prohibited=(p_value#>>'{crossBorderProhibited}')::boolean,cross_border_prohibition_reference=(p_value#>>'{crossBorderProhibitionReference}')::text where id=p_id returning id into saved_id;end if;
when 'partners' then
 if p_id is null then insert into public.fulfilment_partners (registered_name,partner_carrier_ref,agreement_valid_from,agreement_valid_until,status,coverage_evidence,carrier_id) values((p_value#>>'{registeredName}')::text,(p_value#>>'{partnerCarrierRef}')::uuid,(p_value#>>'{agreementValidFrom}')::timestamptz,(p_value#>>'{agreementValidUntil}')::timestamptz,(p_value#>>'{status}')::text,(p_value#>>'{coverageEvidence}')::text,p_carrier_id) returning id into saved_id;
 else update public.fulfilment_partners set registered_name=(p_value#>>'{registeredName}')::text,partner_carrier_ref=(p_value#>>'{partnerCarrierRef}')::uuid,agreement_valid_from=(p_value#>>'{agreementValidFrom}')::timestamptz,agreement_valid_until=(p_value#>>'{agreementValidUntil}')::timestamptz,status=(p_value#>>'{status}')::text,coverage_evidence=(p_value#>>'{coverageEvidence}')::text where id=p_id returning id into saved_id;end if;
end case;
 result:=private.catalog_record(p_kind,saved_id);
 perform private.save_catalog_receipt(p_organization_id,p_member_id,p_carrier_id,p_idempotency_key,hash,result);
 return jsonb_build_object('record',result,'replay',false);
end;$$;

create function private.read_v2_carrier_catalog(op uuid,k text,c uuid,s uuid,i uuid,l integer,f integer) returns jsonb
language plpgsql security definer set search_path='' as $$declare t text; predicate text;r record;result jsonb:='[]';family text;begin
 perform private.carrier_portal_catalog_scope(op,k,c,s,false,i);
 if l is null or l not between 1 and 100 or f is null or f not between 0 and 100000 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 if k in ('assets','capacity-pools','calendars','maintenances','repositioning-blocks','asset-capabilities','capability-definitions') then
  t:=private.fleet_target(k);predicate:=format('carrier_id=%L',c);family:='fleet';
 elsif k in ('drivers','vehicle-combinations','driver-assignments','vehicle-assignments') then
  t:=private.crew_target(k);predicate:=format('carrier_id=%L',c);family:='crew';
 else select table_name,scope_sql into t,predicate from private.catalog_target(k,null,c,s);family:='catalog';end if;
 for r in execute format('select id from public.%I where %s and ($1 is null or id=$1) order by created_at,id limit $2 offset $3',t,predicate)
 using i,l,f loop result:=result||jsonb_build_array(case family when 'fleet' then private.fleet_record(k,r.id)
  when 'crew' then private.crew_record(k,r.id) else private.catalog_record(k,r.id) end);end loop;
 return result;end;$$;
create function public.read_v2_carrier_catalog(p_operator_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_limit integer,p_offset integer)
returns jsonb language sql security invoker set search_path='' as $$select private.read_v2_carrier_catalog(p_operator_id,p_kind,p_carrier_id,p_service_id,p_id,p_limit,p_offset);$$;
create function public.command_v2_carrier_catalog(p_operator_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_idempotency_key uuid,p_expected_version integer,p_value jsonb)
returns jsonb language sql security invoker set search_path='' as $$select private.command_v2_catalog(null,p_operator_id,p_kind,p_carrier_id,p_service_id,p_id,p_idempotency_key,p_expected_version,p_value);$$;

create function public.read_v2_carrier_portal_access() returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED' using errcode='PT401';end if;
 select coalesce(jsonb_agg(jsonb_build_object('carrierId',c.id,'operatorId',op.id,'role',op.role,
  'carrierName',c.name,'displayName',op.display_name) order by c.name,c.id),'[]') into r
 from public.carrier_operators op join public.carriers c on c.id=op.carrier_id
 where op.auth_user_id=auth.uid() and private.identity_carrier_read(c.id);
 return r;end;$$;

create function private.read_v2_carrier_portal_routing(op uuid,k text,c uuid,l integer,f integer) returns jsonb
language plpgsql security definer set search_path='' as $$declare r record;result jsonb:='[]';begin
 if op is distinct from private.identity_carrier(c) then raise exception 'FORBIDDEN_CARRIER_IDENTITY' using errcode='PT403';end if;
 if k not in ('nodes','conditions') or k is null or l is null or l not between 1 and 100 or f is null or f not between 0 and 100000 then
  raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 for r in execute format('select id from public.%I where organization_id is null and (carrier_id is null or carrier_id=$1) order by created_at,id limit $2 offset $3',private.workflow_table(k))
 using c,l,f loop result:=result||jsonb_build_array(private.workflow_record(k,r.id));end loop;return result;end;$$;
create function public.read_v2_carrier_portal_routing(p_operator_id uuid,p_kind text,p_carrier_id uuid,p_limit integer,p_offset integer)
returns jsonb language sql security invoker set search_path='' as $$select private.read_v2_carrier_portal_routing(p_operator_id,p_kind,p_carrier_id,p_limit,p_offset);$$;
revoke all on function private.read_v2_carrier_portal_routing(uuid,text,uuid,integer,integer),public.read_v2_carrier_portal_routing(uuid,text,uuid,integer,integer) from public,anon,authenticated,service_role;
grant execute on function private.read_v2_carrier_portal_routing(uuid,text,uuid,integer,integer),public.read_v2_carrier_portal_routing(uuid,text,uuid,integer,integer) to authenticated;

revoke all on function private.authorize_v2_catalog_before_carrier_portal(uuid,uuid,text,uuid,uuid,boolean,uuid),
 private.authorize_v2_catalog(uuid,uuid,text,uuid,uuid,boolean,uuid),
 private.carrier_portal_catalog_scope(uuid,text,uuid,uuid,boolean,uuid),
 private.catalog_receipt(uuid,uuid,uuid,uuid),private.save_catalog_receipt(uuid,uuid,uuid,uuid,text,jsonb)
 from public,anon,authenticated,service_role;
revoke all on function private.read_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,integer,integer),
 public.read_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,integer,integer),
 public.command_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,uuid,integer,jsonb),
 public.read_v2_carrier_portal_access() from public,anon,authenticated,service_role;
grant execute on function private.read_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,integer,integer),
 public.read_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,integer,integer),
 public.command_v2_carrier_catalog(uuid,text,uuid,uuid,uuid,uuid,integer,jsonb),public.read_v2_carrier_portal_access() to authenticated;
commit;
